 58	/** Drops every `filter` and `diff` assignment (and unset/unspecify forms) from .gitattributes text, macros included. */
 59	export function withoutDrivers(text: string): string {
 60	  return text.split("\n").map((line) => {
 61	    const trimmed = line.trim();
 62	    if (!trimmed || trimmed.startsWith("#")) return line;
 63	    const head = /^("(?:[^"\\]|\\.)*"|\S+)(\s+|$)/.exec(trimmed);
 64	    if (!head) return line;
 65	    const rest = trimmed.slice(head[0].length).split(/\s+/).filter(Boolean);
 66	    return [head[1], ...rest.filter((token) => !/^[-!]?(filter|diff)(=|$)/.test(token))].join(" ");
 67	  }).join("\n");
 68	}
 69	/**
 70	 * The repository states the candidate diff and the debugger snapshot are built for, as one finite predicate over the
 71	 * unit's own index and configuration. Inside it the scratch index (base tree, or a copy of the real index) plus the
 72	 * worktree is a faithful picture of the candidate: every index entry is a plain stage-0 file or symlink whose
 73	 * worktree state git actually checks, and file modes and symlinks are real on the filesystem. Outside it the answer
 74	 * would depend on flags that tell git not to look at the worktree (assume-unchanged, skip-worktree, sparse checkout),
 75	 * on modes the filesystem cannot report (`core.filemode=false`, `core.symlinks=false`), on case folding, on gitlinks
 76	 * (submodules: the diff shows only the pointer), or on an unresolved merge, so it is refused with a reason instead of
 77	 * a guess. Also refused: a workspace that is a subdirectory of its repository (attributes and protected-file
 78	 * listings would be relative to it), a SHA-256 repository, and a `filter=` attribute in any worktree .gitattributes
 79	 * (a clean/smudge filter, such as LFS or git-crypt, makes every filtered file differ from its index blob). Not
 80	 * refused, and covered by tests: detached HEAD, linked worktrees, untracked and ignored files, intent-to-add entries,
 81	 * renames and copies, symlinks, a merge or cherry-pick in progress once resolved in the index. Known gaps, not
 82	 * refused: a `-diff` attribute can make the diff exceed its size limit (reported as too large); `GIT_*` config
 83	 * variables are dropped, so the predicate reads the files' configuration only.
 84	 * `run` is a pinned git call against the repository's own index (never written); `root` is the workspace.
 85	 */
 86	export type SnapshotSupport = { ok: true } | { unsupported: string };
 87	export function snapshotSupport(run: (args: string[]) => string, root: string): SnapshotSupport {
 88	  const config = new Map<string, string>();
 89	  try {
