100	  try { format = run(["rev-parse", "--show-object-format"]).trim(); } catch { /* git before 2.38 knows only SHA-1 */ }
101	  if (format !== "sha1") return refuse(`the repository uses the ${format} object format, which is not supported`, "no workaround");
102	  if (config.get("core.filemode") === "false") return refuse("core.filemode is false, so file modes are not read from disk", "set core.filemode=true");
103	  if (config.get("core.symlinks") === "false") return refuse("core.symlinks is false, so symlinks are checked out as files", "set core.symlinks=true");
104	  if (config.get("core.ignorecase") === "true") return refuse("core.ignorecase is true (a case-insensitive filesystem), so paths cannot be matched exactly", "no workaround");
105	  if (config.get("core.sparsecheckout") === "true") return refuse("a sparse checkout is enabled", "run `git sparse-checkout disable`");
106	  const unmerged = new Set<string>();
107	  for (const entry of run(["ls-files", "-s", "-z"]).split("\0")) {
108	    const m = /^(\d{6}) [0-9a-f]+ (\d)\t([\s\S]*)$/.exec(entry);
109	    if (!m) continue;
110	    if (m[1] === "160000") return refuse(`${m[3].slice(0, 80)} is a submodule (gitlink): only its pointer would be shown, not its content`, "no workaround");
111	    if (m[2] !== "0") unmerged.add(m[3]);
112	  }
113	  if (unmerged.size) return refuse(`${unmerged.size} path(s) have unresolved merge conflicts (for example ${[...unmerged][0].slice(0, 80)})`, "resolve them");
