116	    const tag = entry[0];
117	    const file = entry.slice(2).slice(0, 80);
118	    if (tag === "S" || tag === "s") return refuse(`${file} is marked skip-worktree (sparse checkout), so git does not look at its worktree state`, "run `git update-index --no-skip-worktree`");
