123	    if (!file || file.endsWith("/")) continue;
124	    let text = "";
125	    try { const full = path.join(root, file); if (fs.lstatSync(full).isFile()) text = fs.readFileSync(full, "utf8"); } catch { continue; }
126	    if (/(^|\s)filter=/m.test(text.split("\n").filter((l) => !l.trim().startsWith("#")).join("\n"))) return refuse(`${file.slice(0, 80)} assigns a clean/smudge filter, so worktree content differs from the index by design`, "no workaround");
