157	/** Ignored trees (node_modules, build output) scale with the repository, not the change: about 6 s per 90k files. */
158	const IGNORED_LISTING_TIMEOUT_MS = 180_000;
159	const SOURCE_FILE_MAX = 4 * 1024 * 1024;
160	const SOURCE_TOTAL_MAX = 64 * 1024 * 1024;
161	const ADDED_FILE_MAX = 16 * 1024 * 1024;
162	const SIGNIFICANT_LINE_MIN = 8;
