169	 * file counts as carried: nothing is kept because it could not be compared.
170	 */
171	function protectedContent(sources: Array<{ root: string; file: string }>): { carriedBy(dir: string, relative: string): boolean } {
172	  const hashes = new Set<string>();
173	  const lines = new Set<string>();
174	  let complete = true;
175	  let total = 0;
