183	    } catch { continue; }
184	    // A large `.nexus` file (a flight log) is not a credential source: it is left out instead of failing every new file closed.
185	    if (structural && size > SOURCE_FILE_MAX) continue;
186	    if (!structural) total += size;
187	    if (size > SOURCE_FILE_MAX || total > SOURCE_TOTAL_MAX) { complete = false; continue; }
188	    let data: Buffer;
189	    try { data = fs.readFileSync(path.join(root, file)); } catch { complete = false; continue; }
190	    hashes.add(createHash("sha256").update(data).digest("hex"));
191	    if (structural) continue;
192	    for (const line of significantLines(data)) lines.add(line);
193	  }
194	  return {
195	    carriedBy(dir: string, relative: string): boolean {
196	      if (!complete) return true;
197	      if (hashes.size === 0 && lines.size === 0) return false;
198	      let data: Buffer;
199	      try {
200	        const st = fs.lstatSync(path.join(dir, relative));
201	        if (!st.isFile()) return false;
202	        if (st.size > ADDED_FILE_MAX) return true;
203	        data = fs.readFileSync(path.join(dir, relative));
