217	/**
218	 * The attribute source for a diff: the worktree's .gitattributes files with filter and diff assignments removed, as a
219	 * tree in a private object directory (nothing is written to the repository). Undefined when there are none.
220	 */
221	export function attributesTree(root: string, scratch: string, files: string[]): { tree: string; objects: string } | undefined {
222	  const sources = files.filter((f) => path.posix.basename(f) === ".gitattributes").flatMap((f) => {
223	    try {
224	      const full = path.join(root, f);
225	      const st = fs.lstatSync(full);
226	      return st.isFile() && st.size <= 1024 * 1024 ? [{ file: f, text: withoutDrivers(fs.readFileSync(full, "utf8")) }] : [];
227	    } catch { return []; }
228	  });
229	  if (!sources.length) return undefined;
230	  const objects = path.join(scratch, "attr-objects");
231	  fs.mkdirSync(objects);
232	  const env = { ...safeGitEnv(path.join(scratch, "attr-index")), GIT_OBJECT_DIRECTORY: objects };
233	  const run = (args: string[], input?: string) => execFileSync("git", [...GIT_SAFE, ...args], { cwd: root, env, encoding: "utf8", stdio: [input === undefined ? "ignore" : "pipe", "pipe", "pipe"], timeout: 30_000, ...(input === undefined ? {} : { input }) });
234	  const entries = sources.map(({ file, text }) => `100644 ${run(["hash-object", "-w", "--stdin"], text).trim()}\t${file}\0`);
235	  run(["update-index", "--add", "-z", "--index-info"], entries.join(""));
236	  return { tree: run(["write-tree"]).trim(), objects };
