239	/**
240	 * The candidate diff against `base` (HEAD when absent), for every unit that is shown one: review units and the
241	 * security reviewer. No repository-configured command runs while it is built (see GIT_SAFE and safeGitEnv); a
242	 * filter or diff driver that would still apply makes it fail. It is built from the changed paths and never from parsing diff text: the changed paths come from
243	 * NUL-separated git output with rendering options pinned, the protected ones (the read_file policy, `.nexus`) are
244	 * removed, and the diff is then requested for the remaining paths only (literal pathspecs), so a protected file cannot
245	 * appear in it whatever the repository's diff settings. A rename or copy with either side protected drops both sides
246	 * (the body of a file renamed out of a protected path is still its content).
247	 *
248	 * Untracked files are compared through a scratch index (the base tree plus intent-to-add entries for every untracked
249	 * file, never the repository's own index), so git's rename detection pairs an unstaged move of a protected file with
250	 * its new name instead of showing that name as an unrelated new file. Rename and copy detection stop at git's
251	 * similarity threshold (and `--find-copies-harder` makes an untouched tracked protected file a copy source), so when
252	 * any protected path changed (moved, deleted, edited or added), every added file is omitted too and counted in
253	 * `omittedNew`: a protected file moved and rewritten, or one whose lines were copied out, may otherwise reach the diff
254	 * as an innocent new file. Independently of git's heuristics, an added file is omitted (and counted the same way) when
255	 * it equals a protected file present in the workspace, tracked, untracked or ignored, or shares a significant line
256	 * with one (see `protectedContent`); that covers `cp .env notes.txt` and a partial copy of any size.
257	 * Limits of that comparison, where credential redaction is the only guard: lines pasted from a protected file into a
258	 * file that already existed at the base (modified files are not line-compared); any re-formatting of a protected
259	 * file's lines (quoting, a changed separator, values only, re-encoding), because a line matches only exactly once
260	 * trimmed and is at least 8 characters; and a protected file whose lines are all shorter than that, which is caught
261	 * only by an exact whole-file match. The trade-off is over-omission: a new file sharing a common line (such as
262	 * NODE_ENV=development) with any protected file in the workspace, an ignored `.env*` included, is omitted and noted.
263	 * The pass listing ignored files takes up to IGNORED_LISTING_TIMEOUT_MS (about 6 s per 90k ignored files); a tree too
264	 * large for it fails closed with an error rather than being trusted.
265	 * Any git failure or an unmanageable path count returns an error: nothing is ever kept because it could not be
266	 * classified.
267	 */
268	export interface CandidateDiff { base: string; diff: string; omitted: number; omittedNew: number; omittedNested: number }
269	export function candidateDiff(workspace: string, base: string | undefined, policyWorkspace?: string): CandidateDiff | { error: string } {
270	  const root = path.resolve(workspace);
271	  let scratch: string | undefined;
272	  let attrs: { tree: string; objects: string } | undefined;
273	  // `ownIndex` reads the repository's own index (never written: only listed); everything else uses the scratch index.
274	  const git = (args: string[], options: { okExit?: number[]; input?: string; maxBuffer?: number; ownIndex?: boolean; timeoutMs?: number } = {}): string => {
275	    try {
276	      return execFileSync("git", [...GIT_SAFE, ...args], {
277	        cwd: root, env: safeGitEnv(options.ownIndex ? undefined : path.join(scratch!, "index"), attrs), encoding: "utf8", stdio: [options.input === undefined ? "ignore" : "pipe", "pipe", "pipe"],
278	        timeout: options.timeoutMs ?? 30_000, maxBuffer: options.maxBuffer ?? GIT_MAX_BUFFER, ...(options.input === undefined ? {} : { input: options.input }),
279	      });
280	    } catch (err: any) {
281	      if (typeof err?.status === "number" && options.okExit?.includes(err.status) && typeof err.stdout === "string") return err.stdout;
282	      throw err;
283	    }
284	  };
285	  try {
286	    scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-candidate-index-"));
287	    // The policy is the operator's (their workspace), not whatever a unit's own worktree holds: an untracked
288	    // .nexus-security.json never reaches a worktree.
289	    const security = new SecurityManager(policyWorkspace ?? root);
290	    // A base read from persisted JSON is resolved as a commit before use: a value shaped like an option is refused.
291	    const support = snapshotSupport((args) => git(args, { ownIndex: true, maxBuffer: LISTING_MAX_BUFFER }), root);
292	    if ("unsupported" in support) return { error: `automatic inputs are not available for this repository state: ${support.unsupported}; give the unit explicit inputs instead` };
293	    const commit = git(["rev-parse", "--verify", "--end-of-options", `${base ?? "HEAD"}^{commit}`]).trim();
294	    git(["read-tree", "--end-of-options", commit]);
295	    const listing = (args: string[], ownIndex = false, timeoutMs?: number) => git(["ls-files", "-z", ...args], { maxBuffer: LISTING_MAX_BUFFER, ownIndex, timeoutMs }).split("\0").filter(Boolean);
296	    // New paths: untracked files git does not ignore, plus files tracked now but not at the base (a force-added file
297	    // can match .gitignore and still be part of the candidate).
298	    const atBase = new Set(listing([]));
299	    // A path tracked since the base but already removed from disk is a deletion against nothing: it has no content to
300	    // show, and git would reject it as a pathspec.
301	    const onDisk = (p: string) => { try { fs.lstatSync(path.join(root, p)); return true; } catch { return false; } };
302	    const ownIndex = new Set(listing([], true));
303	    // Untracked, non-ignored entries, listed once. A directory entry (trailing slash) is an untracked nested git
304	    // repository, which `git add` refuses: it is skipped and counted rather than failing every review.
305	    const others = listing(["--others", "--exclude-standard"]);
306	    const omittedNested = others.filter((p) => p.endsWith("/")).length;
307	    const untracked = others.filter((p) => !p.endsWith("/"));
308	    attrs = attributesTree(root, scratch, [...new Set([...untracked, ...ownIndex])]);
309	    // A path tracked at the base but removed from the real index (`git rm --cached`) is part of the candidate as a
310	    // deletion even when the file stays on disk: force it out of the scratch index too (its entry can match neither HEAD nor the worktree), and never re-add it as new.
311	    const removed = [...atBase].filter((p) => !ownIndex.has(p));
312	    if (removed.length) {
313	      git(["--literal-pathspecs", "rm", "--cached", "--force", "--quiet", "--ignore-unmatch", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${removed.join("\0")}\0` });
314	    }
315	    const removedSet = new Set(removed);
316	    const added = new Set([
317	      ...untracked.filter((p) => !removedSet.has(p)),
318	      ...[...ownIndex].filter((p) => !atBase.has(p) && onDisk(p)),
319	    ]);
320	    if (added.size) {
321	      git(["--literal-pathspecs", "add", "--force", "--intent-to-add", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${[...added].join("\0")}\0` });
322	    }
323	    // Comparing worktree content runs a path's clean filter, so before any diff every path is checked for a filter or
324	    // diff driver the stripped attribute source did not neutralise ($GIT_DIR/info/attributes, or a worktree
325	    // .gitattributes on Git before 2.40); one that applies is refused, never run. The check is batched so the
326	    // repository's size never turns into a failure.
327	    const refusal = driverRefusal((args, input) => git(args, { input }), listing([]));
328	    if (refusal) return { error: refusal };
329	    // name-status with rename detection (no limit on the exhaustive pass), only to learn which paths belong together.
330	    const tokens = git(["diff", "--name-status", "-z", "-M", "-C", "--find-copies-harder", "-l0", "--relative", "--no-ext-diff", "--no-textconv", "--end-of-options", commit, "--"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0");
331	    const groups: Array<{ status: string; paths: string[] }> = [];
332	    for (let i = 0; i < tokens.length; ) {
333	      const status = tokens[i++];
334	      if (!status) continue;
335	      const count = status[0] === "R" || status[0] === "C" ? 2 : 1;
336	      const paths = tokens.slice(i, i + count);
337	      i += count;
338	      if (paths.length !== count || paths.some((p) => !p)) return { error: "git reported a changed path that could not be read" };
339	      groups.push({ status, paths });
340	    }
341	    if (groups.length > MAX_DIFF_PATHS) return { error: `the change touches more than ${MAX_DIFF_PATHS} paths; scope it with explicit inputs` };
342	    const isProtected = (group: { paths: string[] }) => group.paths.some((p) => inputPathProtection(security, p) !== undefined);
343	    const protectedChanged = groups.some(isProtected);
344	    // Git's copy detection stops at its similarity threshold and never sees an ignored protected file, so an added file
345	    // is also compared with the content of every protected file present in the workspace.
346	    const ignored = listing(["--others", "--ignored", "--exclude-standard"], false, IGNORED_LISTING_TIMEOUT_MS).filter((p) => !p.endsWith("/"));
347	    const isolated = path.resolve(policyWorkspace ?? root) !== root;
348	    const protectedSources = [...new Set([...atBase, ...ownIndex, ...untracked, ...ignored])]
349	      .filter((p) => inputPathProtection(security, p) !== undefined).map((file) => ({ root, file }));
350	    // A unit's worktree lacks the operator's untracked and ignored secrets (.env), so those are compared too.
351	    if (isolated) {
352	      const operator = path.resolve(policyWorkspace!);
353	      // Tracked, untracked and ignored files of the operator's repository. A failure (timeout, buffer) propagates: the
354	      // comparison is never silently skipped.
355	      for (const extra of [[], ["--ignored"]]) {
356	        const listed = execFileSync("git", [...GIT_SAFE, "ls-files", "-z", "--cached", "--others", ...extra, "--exclude-standard"], {
357	          cwd: operator, env: safeGitEnv(undefined), encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: IGNORED_LISTING_TIMEOUT_MS, maxBuffer: LISTING_MAX_BUFFER,
358	        }).split("\0").filter((p) => p && !p.endsWith("/") && inputPathProtection(security, p) !== undefined);
359	        for (const file of listed) protectedSources.push({ root: operator, file });
360	      }
361	    }
362	    const sources = protectedContent(protectedSources);
363	    let omitted = 0;
364	    let omittedNew = 0;
365	    const allowed: string[] = [];
366	    for (const group of groups) {
367	      if (isProtected(group)) omitted++;
368	      // A copy or rename is a new file too: its destination is compared with the protected content like an added file.
369	      else if ("ACR".includes(group.status[0]) && ((group.status[0] === "A" && protectedChanged) || sources.carriedBy(root, group.paths[group.paths.length - 1]))) omittedNew++;
370	      else allowed.push(...group.paths);
371	    }
372	    const diff = allowed.length ? git(["diff", ...DIFF_FLAGS, "--end-of-options", commit, "--", ...allowed.map((p) => `:(literal)${p}`)]) : "";
373	    return { base: commit, diff, omitted, omittedNew, omittedNested };
374	  } catch (err: any) {
375	    if (err?.code === "ENOBUFS" || /ENOBUFS/.test(String(err?.message))) {
376	      return { error: `the candidate diff is too large to show (over ${GIT_MAX_BUFFER / (1024 * 1024)} MiB); scope it with explicit inputs` };
377	    }
378	    return { error: `git could not produce the diff (${String(err?.message ?? err).split("\n")[0].slice(0, 120)})` };
379	  } finally {
380	    if (scratch) fs.rmSync(scratch, { recursive: true, force: true });
381	  }
382	}
