384	/** Credential-redacted and bounded to the input limit, with a marker when cut. */
385	export function boundedRedactedInput(text: string): string {
386	  const redacted = redactForPersistence(text);
387	  return redacted.length > MAX_SPECIALIST_INPUT_CHARS ? `${redacted.slice(0, MAX_SPECIALIST_INPUT_CHARS - 16)}\n[truncated]` : redacted;
388	}

