 15	 * Whether a workspace-relative path is off limits as input text: protected by the workspace security policy (the one
 16	 * read_file applies), or inside Nexus's own state directory (`.nexus`, compared case-insensitively because the
 17	 * filesystem may be).
 18	 */
 19	export function inputPathProtection(security: SecurityManager, relative: string): string | undefined {
 20	  const segments = relative.split(/[\\/]/).map((segment) => segment.toLowerCase());
 21	  if (segments.includes(".nexus")) return "inside .nexus";
 22	  const check = security.isPathProtected(relative);
 23	  return check.protected ? (check.reason ?? "protected by the security policy") : undefined;
 24	}
