 93	    }
 94	  } catch (err: any) {
 95	    if (err?.status !== 1) throw err; // 1 = none of them is set: every default is inside the domain
 96	  }
 97	  const refuse = (what: string, fix: string): SnapshotSupport => ({ unsupported: `${what}; ${fix}` });
