131	const DIFF_FLAGS =["--no-color", "--no-ext-diff", "--no-textconv", "--no-renames", "--relative"];
132	const MAX_DIFF_PATHS = 2_000;
133	const GIT_MAX_BUFFER = 4 * 1024 * 1024;
134	/** Path listings scale with the repository, not the change, so they get room for very large repositories. */
135	const LISTING_MAX_BUFFER = 256 * 1024 * 1024;
136	/** Paths per `check-attr` call, so its output stays small whatever the repository's size. */
137	const ATTR_BATCH = 1_000;
138	
139	/**
140	 * Refuses (returns why) when a filter or diff driver still applies to any of `files` under the pinned attribute
141	 * source, which only `$GIT_DIR/info/attributes` (or a worktree .gitattributes on Git before 2.40) can still assign.
142	 * `run` is a pinned git call that takes stdin. Batched so a repository's size never becomes a failure.
143	 */
144	export function driverRefusal(run: (args: string[], input: string) => string, files: string[]): string | undefined {
145	  for (let start = 0; start < files.length; start += ATTR_BATCH) {
146	    const batch = files.slice(start, start + ATTR_BATCH);
